@slots literal
{
  "holder": "Nadia",
  "openingBalance": 100,
  "annualInterest": 10,
  "years": 4
}

@answer jsEval
const slots = $slots;
probe(Number.isInteger(slots.openingBalance) && slots.openingBalance >= 0, "the opening balance must be a whole number of units");
probe(Number.isInteger(slots.annualInterest) && slots.annualInterest > 0, "the yearly interest must be a positive whole number of units");
probe(Number.isInteger(slots.years) && slots.years > 0, "the term must be a positive whole number of years");
const balance = slots.openingBalance + slots.annualInterest * slots.years;
probe(balance > slots.openingBalance, "the account must grow after the interest is added");
return balance + " units.";

